324	func TestExpiryBoundaryAndReevaluation(t *testing.T) {
325		// 证书截止日为 2026-10-02：当天起即到期；每次查询都按当前日期重新判断。
326		clock := &fakeClock{t: mustDate(t, "2026-10-01")}
327		path := filepath.Join(t.TempDir(), "ledger.json")
328		l, err := openAt(path, clock.now)
329		if err != nil {
330			t.Fatalf("open: %v", err)
331		}
332		mustRegister(t, l, "M-1", "万用表", 0.5)
333		mustAddCert(t, l, CertificateInput{
334			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-01-01",
335			Expiry: "2026-10-02", Method: "m", Error: 0.1, Summary: "s",
336		})
337		_ = l.SetStatus("M-1", StatusInUse)
338	
339		d, _ := l.RequestUse("M-1")
340		if !d.Allowed {
341			t.Fatalf("截止日前一天应允许使用，得到 %v", d.Reasons)
342		}
343	
344		// 到了截止日当天：不修改任何数据，仅时钟前进，再次申请即被拒绝。
345		clock.t = mustDate(t, "2026-10-02")
346		d, _ = l.RequestUse("M-1")
347		if d.Allowed || !containsReason(d.Reasons, "到期") {
348			t.Fatalf("截止日当天应判到期并拒绝，得到 %v", d.Reasons)
349		}
350	
351		// 重新打开同一台账，按打开时的本机日期判断，仍是到期。
352		reopened, err := openAt(path, func() time.Time { return mustDate(t, "2026-10-03") })
353		if err != nil {
354			t.Fatalf("reopen: %v", err)
355		}
356		r, err := reopened.Review("M-1")
357		if err != nil {
358			t.Fatalf("review after reopen: %v", err)
359		}
360		if r.CanUse || r.Latest == nil || !r.Latest.Expired {
361			t.Fatalf("重开台账后应按新日期判到期，canUse=%v", r.CanUse)
362		}
363	}
364	
365	func TestUseReasonsAllListedAndRecorded(t *testing.T) {
366		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
367		l := newTestLedger(t, clock)
368		mustRegister(t, l, "M-1", "万用表", 0.5)
369		mustRegister(t, l, "M-2", "示波器", 0.5)
370	
371		// 待校准 + 无证书：两个原因都要列出，且留痕。
372		d, err := l.RequestUse("M-1")
373		if err != nil || d.Allowed {
374			t.Fatalf("待校准无证书应拒绝，err=%v", err)
375		}
376		if !containsReason(d.Reasons, "待校准") || !containsReason(d.Reasons, "没有校准证书") {
377			t.Fatalf("应列出全部适用原因，得到 %v", d.Reasons)
378		}
379	
380		// 未知编号明确报错且不新增记录。
381		before := len(l.UsageRecords())
382		if _, err := l.RequestUse("NOPE"); !errors.Is(err, ErrNotFound) {
383			t.Fatalf("未知编号应报 ErrNotFound，得到 %v", err)
384		}
385		if len(l.UsageRecords()) != before {
386			t.Fatal("未知编号的使用申请不应留痕")
387		}
388		if _, err := l.RequestUse("   "); !IsValidation(err) {
389			t.Fatalf("空白编号应报校验错误，得到 %v", err)
390		}
391	
392		// 停用 + 到期 + 超差同时存在时，原因全部列出。
393		mustAddCert(t, l, CertificateInput{
394			InstrumentID: "M-2", Number: "C-2", CalDate: "2025-01-01",
395			Expiry: "2025-12-31", Method: "m", Error: 0.9, Summary: "s",
396		})
397		_ = l.SetStatus("M-2", StatusRetired)
398		d, _ = l.RequestUse("M-2")
399		if d.Allowed {
400			t.Fatal("应拒绝")
401		}
402		for _, want := range []string{"停用", "超差", "到期"} {
403			if !containsReason(d.Reasons, want) {
404				t.Fatalf("原因缺少 %q：%v", want, d.Reasons)
405			}
406		}
407	
408		// 获准使用同样留痕。
409		_ = l.SetStatus("M-1", StatusInUse)
410		mustAddCert(t, l, CertificateInput{
411			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
412			Expiry: "2027-09-01", Method: "m", Error: 0, Summary: "s",
413		})
414		d, _ = l.RequestUse("M-1")
415		if !d.Allowed {
416			t.Fatalf("在用+最近证书合格+未到期应获准，得到 %v", d.Reasons)
417		}
418		// 假时钟下多条记录时间相同，直接找到 M-1 的最新一条核对留痕。
419		var allowedRec *UsageRecord
420		recs := l.UsageRecords()
421		for i := range recs {
422			if recs[i].InstrumentID == "M-1" && recs[i].Allowed {
423				allowedRec = &recs[i]
424			}
425		}
426		if allowedRec == nil || allowedRec.RequestedAt == "" {
427			t.Fatalf("允许记录未正确保存：%+v", recs)
428		}
429	}
